        int size = infos.size();
        mComponentSet = new ComponentName[size];

        for (int i = 0; i < size; i++) {
            ResolveInfo info = infos.get(i);
            mComponentSet[i] = new ComponentName(info.activityInfo.packageName,
                    info.activityInfo.name);
        }
