                val = RotaryProtos.FOCUS_RIGHT;
                break;
            case View.FOCUS_DOWN:
                val = RotaryProtos.FOCUS_DOWN;
                break;
            default:
                throw new IllegalArgumentException("Invalid direction: " + focusDirection);
        }
        dumpOutputStream.write(fieldName, fieldId, val);
    }

