        Toast.makeText(getApplicationContext(),"before if"+speed, Toast.LENGTH_LONG).show();
        speed=(int)loc.getSpeed();
        Log.d("Mit",""+speed);
        if (loc.hasSpeed()) {
            speed = (int) (loc.getSpeed() * 3.6);
            Toast.makeText(getApplicationContext(),"Speed is:"+speed, Toast.LENGTH_LONG).show();
            if (speed > 0)
                r.play();
            else
                r.stop();
        }
        else
        {
            r.stop();
        }
    }

