            row.setTag(holder);
        }
        else {
            holder = (ViewHolder)row.getTag();
        }

        Member vehicle = member_list.get(pos);

        holder.pretty.setText(vehicle.pretty_name);
        holder.details.setText(vehicle.year+" "+vehicle.make+" "+vehicle.model);

        return row;
    }

