        public void itemStateChanged(ItemEvent e)
        {
            @SuppressWarnings("unchecked")
            JComboBox<String> cb = (JComboBox<String>) e.getSource();
            String text = (String)cb.getSelectedItem();
            if (text == null || "".equals(text))
                return;
            boolean exists= false;
